export interface Org {
  id?: string;
  name?: string;
  [key: string]: unknown;
}

export interface User {
  id?: string;
  orgId: string;
  org?: Org;
  [key: string]: unknown;
}

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status} for ${url}`);
  }
  return (await response.json()) as T;
}

export async function loadUser(id: string): Promise<User> {
  const user = await fetchJson<User>(`/api/users/${encodeURIComponent(id)}`);
  const org = await fetchJson<Org>(`/api/orgs/${encodeURIComponent(user.orgId)}`);
  return { ...user, org };
}

export async function loadUsers(ids: string[]): Promise<User[]> {
  return await Promise.all(ids.map((id) => loadUser(id)));
}

- `Rc<RefCell<T>>`: single-threaded shared ownership + runtime-checked interior mutability. Not `Send`/`Sync`. Use when data is shared within one thread/event loop. Borrow conflicts panic.
- `Arc<Mutex<T>>`: atomic shared ownership across threads + blocking mutual exclusion. Use when multiple threads need shared mutable state. Locks can block; poisoning possible.

```rust
// Rc<RefCell<T>>
use std::rc::Rc;
use std::cell::RefCell;

let shared = Rc::new(RefCell::new(0));
let a = shared.clone();
let b = shared.clone();

*a.borrow_mut() += 1;
println!("{}", b.borrow()); // 1
```

```rust
// Arc<Mutex<T>>
use std::sync::{Arc, Mutex};
use std::thread;

let counter = Arc::new(Mutex::new(0));
let c = counter.clone();

let handle = thread::spawn(move || {
    *c.lock().unwrap() += 1;
});

handle.join().unwrap();
println!("{}", *counter.lock().unwrap()); // 1
```

Rule of thumb: single-threaded → `Rc<RefCell<T>>`; multi-threaded → `Arc<Mutex<T>>`.
